import z3
import itertools

n = 15
target_edges = 23

# Edge variables
edge_vars = {}
for i in range(n):
    for j in range(i+1, n):
        edge_vars[(i,j)] = z3.Bool(f"e_{i}_{j}")

# Helper: get edge var
def get_edge(i, j):
    if i < j:
        return edge_vars[(i,j)]
    else:
        return edge_vars[(j,i)]

# Constraint: at least target_edges
edge_count = z3.Sum([z3.If(edge_vars[(i,j)], 1, 0) for (i,j) in edge_vars])
constraints = [edge_count >= target_edges]

solver = z3.Solver()
solver.add(constraints)

# We'll do lazy cycle checking
def find_short_cycle(model):
    """Given a model, find a cycle of length <= 6, or return None."""
    # Build adjacency
    adj = {i: [] for i in range(n)}
    for (i,j), v in edge_vars.items():
        if z3.is_true(model[v]):
            adj[i].append(j)
            adj[j].append(i)

    # BFS from each vertex to find shortest cycle
    for start in range(n):
        parent = [-1]*n
        dist = [-1]*n
        queue = [start]
        dist[start] = 0
        for u in queue:
            for v in adj[u]:
                if v == parent[u]:
                    continue
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                else:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len <= 6:
                        # Reconstruct cycle
                        cycle = []
                        # Go up from u to common ancestor
                        a, b = u, v
                        while a != b:
                            if dist[a] >= dist[b]:
                                cycle.append(a)
                                a = parent[a]
                            else:
                                cycle.append(b)
                                b = parent[b]
                        cycle.append(a)
                        # Also addv and u? Actually we have the cycle: u -> ... -> common -> ... -> v -> u
                        # Let's reconstruct properly
                        path_u = [u]
                        while path_u[-1] != a:
                            path_u.append(parent[path_u[-1]])
                        path_v = [v]
                        while path_v[-1] != a:
                            path_v.append(parent[path_v[-1]])
                        cycle = path_u + path_v[::-1]
                        return cycle
    return None

# Iterative solving
max_iterations = 100
for iteration in range(max_iterations):
    print(f"Iteration {iteration}: solving...")
    result = solver.check()
    if result == z3.sat:
        model = solver.model()
        cycle = find_short_cycle(model)
        if cycle is None:
            print("Found valid graph!")
            edges = []
            for (i,j), v in edge_vars.items():
                if z3.is_true(model[v]):
                    edges.append((i,j))
            print("Edges:", edges)
            print("Number of edges:", len(edges))
            break
        else:
            print(f"Found short cycle of length {len(cycle)}: {cycle}")
            # Add constraint: not all edges of this cycle
            edges_in_cycle = []
            for k in range(len(cycle)):
                u = cycle[k]
                v = cycle[(k+1)%len(cycle)]
                edges_in_cycle.append(get_edge(u, v))
            solver.add(z3.Not(z3.And(edges_in_cycle)))
    else:
        print("UNSAT")
        break

